const utils = global.get("utils");                                                                                                                                         
const base_url = global.get("parat_bridge").base_urls.rayvn;                                                                                                               

const headers = { "Authorization": "Bearer " + msg.payload.client_specific.api_key };                                                                                      
const group_id = msg.group_id;                                                                                                                                             

const build_tag_msg = (tag) => ({
    headers,
    url:  base_url + "/tags",
    body: { ...utils.RAYVN_TAGS[tag], group: { id: group_id } }                                                                                                            
});

return [[ build_tag_msg("WASOS"), build_tag_msg("PARAT_BRIDGE") ]];

const config = msg.payload

if (!config.client_specific.api_key) {
    return null
}

const user = JSON.parse(atob(config.client_specific.api_key.split(".")[1]));
msg.group_id = user.group.id
return msg;
